package his.infrastructure.security;

import his.infrastructure.persistence.repositories.UserJpaRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.AuthenticationProvider;
import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.core.userdetails.UsernameNotFoundException;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;

@Configuration
@RequiredArgsConstructor
public class AppConfig {

    private final UserJpaRepository userJpaRepository;

    @Bean // Para que Spring lo pueda inyectar
    public UserDetailsService userDetailsService() {
        return username -> userJpaRepository.findByEmailPaciente(username)
                .orElseThrow(() -> new UsernameNotFoundException("Usuario no encontrado: " + username));
    }

    @Bean//Se utiliza en SecurityConfig, este es el proveedor de autenticación
    public AuthenticationProvider authenticationProvider() {
        DaoAuthenticationProvider authProvider = new DaoAuthenticationProvider(userDetailsService());
        authProvider.setPasswordEncoder(passwordEncoder());
        return authProvider;
    }

    @Bean//Para encriptar las claves que generemos
    public PasswordEncoder passwordEncoder() {
        return  new BCryptPasswordEncoder();
    }

    @Bean//Para que la inyección de la interfaz an el AuthServiceImpl pueda utilizarse
    public AuthenticationManager authenticationManager(AuthenticationConfiguration config) throws Exception {
        return config.getAuthenticationManager();//Es una clase que nos permite gestionar la autenticación por medio de una request(usuario, password)
    }
}

package his.infrastructure.security;

import his.infrastructure.persistence.repositories.UserJpaRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.http.converter.json.Jackson2ObjectMapperBuilder;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.AuthenticationProvider;
import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.core.userdetails.UsernameNotFoundException;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;

@Configuration
@RequiredArgsConstructor
public class AppConfig {

    private final UserJpaRepository userJpaRepository;

    @Bean // Para que Spring lo pueda inyectar
    public UserDetailsService userDetailsService() {
        return username -> userJpaRepository.findByEmailPaciente(username)
                .orElseThrow(() -> new UsernameNotFoundException("Usuario no encontrado: " + username));
    }

    @Bean//Se utiliza en SecurityConfig, este es el proveedor de autenticación
    public AuthenticationProvider authenticationProvider() {
        DaoAuthenticationProvider authProvider = new DaoAuthenticationProvider(userDetailsService());
        authProvider.setPasswordEncoder(passwordEncoder());
        return authProvider;
    }

    @Bean//Para encriptar las claves que generemos
    public PasswordEncoder passwordEncoder() {
        return  new BCryptPasswordEncoder();
    }

    @Bean // Asegura que haya un ObjectMapper disponible para inyección
    public ObjectMapper objectMapper(Jackson2ObjectMapperBuilder builder) {
        return builder.build();
    }

    @Bean//Para que la inyección de la interfaz an el AuthServiceImpl pueda utilizarse
    public AuthenticationManager authenticationManager(AuthenticationConfiguration config) throws Exception {
        return config.getAuthenticationManager();//Es una clase que nos permite gestionar la autenticación por medio de una request(usuario, password)
    }
}

package his.infrastructure.security;

import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.authentication.AuthenticationProvider;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.CorsConfigurationSource;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;

import java.util.List;

@Configuration
@EnableWebSecurity
@RequiredArgsConstructor
@EnableMethodSecurity
public class SecurityConfig {

    private final JwtFilter jwtFilter;
    private final AuthenticationProvider authenticationProvider;

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        return http
                // Configuración CORS (permitimos llamadas desde el frontend)
                .cors(cors -> cors.configurationSource(corsConfigurationSource()))
                .csrf(csrf -> csrf.disable())

                .sessionManagement(sess -> sess.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authenticationProvider(authenticationProvider)

                // Rutas públicas y protegidas
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers(
                                "/api/auth/register",
                                "/api/auth/register/personal",
                                "/api/auth/register/admin",
                                "/api/auth/authenticate",
                                "/api/auth/logout",
                                "/api/catalogs/**",
                                "/v3/api-docs/**",
                                "/swagger-ui/**",
                                "/swagger-ui.html",
                                "/swagger-ui-custom.html"
                        ).permitAll()
                        // AppointmentAttention: DOCTOR total, ADMIN solo lectura
                        .requestMatchers("GET", "/api/appointments/attention/**").hasAnyAuthority("DOCTOR", "ADMIN")
                        .requestMatchers("POST", "/api/appointments/attention/**").hasAuthority("DOCTOR")
                        .requestMatchers("PATCH", "/api/appointments/attention/**").hasAuthority("DOCTOR")
                        .requestMatchers("/api/patients/register").hasAnyAuthority("ADMIN", "DOCTOR", "ENFERMERA", "LABORATORISTA", "FARMACEUTICO", "ADMINISTRATIVO", "RECEPCION")
                        .requestMatchers("/api/patients/triage").hasAnyAuthority("ADMIN", "DOCTOR", "ENFERMERA", "LABORATORISTA", "FARMACEUTICO", "ADMINISTRATIVO", "RECEPCION")
                        .requestMatchers("/api/patients/**").hasAnyAuthority("ADMIN", "DOCTOR", "ENFERMERA", "LABORATORISTA", "FARMACEUTICO", "ADMINISTRATIVO", "RECEPCION")
                        .requestMatchers("/api/laboratory/**").hasAnyAuthority("LABORATORISTA", "DOCTOR", "ADMIN")
                        .requestMatchers("/api/pharmacy/prescriptions/**").hasAnyAuthority("FARMACEUTICO", "DOCTOR", "ADMIN")
                        .requestMatchers("/api/pharmacy/dispense").hasAnyAuthority("FARMACEUTICO", "ADMIN")
                        .requestMatchers("/api/pharmacy/medicines").hasAnyAuthority("FARMACEUTICO", "DOCTOR", "ADMIN")
                        .requestMatchers("/api/pharmacy/reminders/**").authenticated()
                        .anyRequest().authenticated()
                )

                // Agregamos el filtro JWT antes del filtro de autenticación
                .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class)

                .build();
    }

    // Configuración CORS global (puedes ajustar dominios según tu entorno)
    @Bean
    public CorsConfigurationSource corsConfigurationSource() {
        CorsConfiguration config = new CorsConfiguration();
        // Permitir frontend local y despliegues de Azure Static Web Apps.
        config.setAllowedOriginPatterns(List.of(
                "http://localhost:5173",
                "http://localhost:5174",
                "http://localhost:5175",
                "http://localhost:5176",
                "http://localhost:5177",
                "http://localhost:5178",
                "http://127.0.0.1:5173",
                "https://*.azurestaticapps.net"
        ));
        config.setAllowedMethods(List.of("GET", "POST", "PUT", "DELETE", "OPTIONS", "PATCH"));
        config.setAllowedHeaders(List.of("Authorization", "Content-Type", "Accept"));
        config.setAllowCredentials(true);
        config.setExposedHeaders(List.of("Authorization"));
        config.setMaxAge(3600L);

        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration("/**", config);
        return source;
    }
}

package his.infrastructure.security;

import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.authentication.AuthenticationProvider;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.CorsConfigurationSource;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;

import java.util.List;
import org.springframework.http.HttpMethod;

@Configuration
@EnableWebSecurity
@RequiredArgsConstructor
@EnableMethodSecurity
public class SecurityConfig {

    private final JwtFilter jwtFilter;
    private final AuthenticationProvider authenticationProvider;

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        return http
                // Configuración CORS (permitimos llamadas desde el frontend)
                .cors(cors -> cors.configurationSource(corsConfigurationSource()))
                .csrf(csrf -> csrf.disable())

                .sessionManagement(sess -> sess.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authenticationProvider(authenticationProvider)

                // Rutas públicas y protegidas
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers(
                                "/api/auth/register",
                                "/api/auth/register/personal",
                                "/api/auth/register/admin",
                                "/api/auth/authenticate",
                                "/api/auth/logout",
                                "/api/catalogs/**",
                                "/v3/api-docs/**",
                                "/swagger-ui/**",
                                "/swagger-ui.html",
                                "/swagger-ui-custom.html"
                        ).permitAll()
                        // AppointmentAttention: DOCTOR total, ADMIN solo lectura
                        .requestMatchers(HttpMethod.GET, "/api/appointments/attention/**").hasAnyAuthority("DOCTOR", "ADMIN")
                        .requestMatchers(HttpMethod.POST, "/api/appointments/attention/**").hasAuthority("DOCTOR")
                        .requestMatchers(HttpMethod.PATCH, "/api/appointments/attention/**").hasAuthority("DOCTOR")
                        .requestMatchers("/api/patients/register").hasAnyAuthority("ADMIN", "DOCTOR", "ENFERMERA", "LABORATORISTA", "FARMACEUTICO", "ADMINISTRATIVO", "RECEPCION")
                        .requestMatchers("/api/patients/triage").hasAnyAuthority("ADMIN", "DOCTOR", "ENFERMERA", "LABORATORISTA", "FARMACEUTICO", "ADMINISTRATIVO", "RECEPCION")
                        .requestMatchers("/api/patients/**").hasAnyAuthority("ADMIN", "DOCTOR", "ENFERMERA", "LABORATORISTA", "FARMACEUTICO", "ADMINISTRATIVO", "RECEPCION")
                        .requestMatchers("/api/laboratory/**").hasAnyAuthority("LABORATORISTA", "DOCTOR", "ADMIN")
                        .requestMatchers("/api/pharmacy/prescriptions/**").hasAnyAuthority("FARMACEUTICO", "DOCTOR", "ADMIN")
                        .requestMatchers("/api/pharmacy/dispense").hasAnyAuthority("FARMACEUTICO", "ADMIN")
                        .requestMatchers("/api/pharmacy/medicines").hasAnyAuthority("FARMACEUTICO", "DOCTOR", "ADMIN")
                        .requestMatchers("/api/pharmacy/reminders/**").authenticated()
                        .anyRequest().authenticated()
                )

                // Agregamos el filtro JWT antes del filtro de autenticación
                .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class)

                .build();
    }

    // Configuración CORS global (puedes ajustar dominios según tu entorno)
    @Bean
    public CorsConfigurationSource corsConfigurationSource() {
        CorsConfiguration config = new CorsConfiguration();
        // Permitir frontend local y despliegues de Azure Static Web Apps.
        config.setAllowedOriginPatterns(List.of(
                "http://localhost:5173",
                "http://localhost:5174",
                "http://localhost:5175",
                "http://localhost:5176",
                "http://localhost:5177",
                "http://localhost:5178",
                "http://127.0.0.1:5173",
                "https://*.azurestaticapps.net"
        ));
        config.setAllowedMethods(List.of("GET", "POST", "PUT", "DELETE", "OPTIONS", "PATCH"));
        config.setAllowedHeaders(List.of("Authorization", "Content-Type", "Accept"));
        config.setAllowCredentials(true);
        config.setExposedHeaders(List.of("Authorization"));
        config.setMaxAge(3600L);

        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration("/**", config);
        return source;
    }
}

