    } finally {
      setLoadingAction(false)
    }
  }

  return (
    <div className="h-screen bg-slate-100 text-slate-800 flex overflow-hidden">
      <AdminSidebar
        email={user?.email}
        role={user?.role}
        loading={loadingLogout}
        activeSection="consultation"
